INSERT INTO "interpersonal_skills" ("skill_id", "name", "description") VALUES ("1", "Communication", "One of the most important interpersonal skills in any job is communication. Whether you work in IT, customer service, construction, or any other industry, you will need to be able to communicate clearly and effectively with others through both oral and written communications.");
INSERT INTO "interpersonal_skills" ("skill_id", "name", "description") VALUES ("2", "Conflict Management", "Whether you are a manager or an employee, you will likely need to resolve conflicts at some point in your job. This might involve solving an issue between two staff members, between yourself and a colleague, or between a client and your company.");
INSERT INTO "interpersonal_skills" ("skill_id", "name", "description") VALUES ("3", "Empathy", "Part of being a good manager, employee, or colleague is the ability to understand and show empathy for others. If a customer or colleague calls with a complaint, for example, you will need to listen thoughtfully to the person’s concerns and express compassion for their issue. Empathy is an important skill that will help you get along with everyone in the workplace.");
INSERT INTO "interpersonal_skills" ("skill_id", "name", "description") VALUES ("4", "Leadership", "Even if you are not a manager, it is important to have some leadership experience and ability. Leadership requires being able to motivate and encourage others and help a team achieve success.");
INSERT INTO "interpersonal_skills" ("skill_id", "name", "description") VALUES ("5", "Listening", "Listening is a skill that goes hand in hand with good communication. While you need to be able to express your own ideas, you also need to thoughtfully listen to the ideas of others. This will help your clients, employers, colleagues, and employees feel respected and valued.");
INSERT INTO "interpersonal_skills" ("skill_id", "name", "description") VALUES ("6", "Negotiation", "Negotiation is an important skill for many positions. Depending on the specific job, it might involve creating formal agreements (or contracts) between clients or helping colleagues solve a problem and determine a solution. To be a good negotiator, you have to be able to listen to others, use creative problem-solving, and arrive at an outcome that satisfies everyone.");
INSERT INTO "interpersonal_skills" ("skill_id", "name", "description") VALUES ("7", "Positive Attitude", "Employers want to hire employees who make the office a brighter place. They want people with a friendly, positive demeanor. This doesn’t mean you have to be the most social person in the office, but you have to be willing to develop some sort of a positive rapport with your colleagues.");
INSERT INTO "interpersonal_skills" ("skill_id", "name", "description") VALUES ("8", "Teamwork", "Even if your job involves a lot of independent work, you still need to be able to collaborate with others. Teamwork involves a number of the skills already mentioned: you need to be able to listen to others, communicate your own goals, motivate your team, and resolve any conflicts that may arise.");
